'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var Float64Array = require( '@stdlib/array/float64' );
var dlamch = require( '@stdlib/lapack/base/dlamch' );
var dlaqsp = require( './../lib/dlaqsp.js' );


// FIXTURES //

var fixtureU = require( './fixtures/column_major_upper.json' );
var fixtureL = require( './fixtures/column_major_lower.json' );
var fixtureU1 = require( './fixtures/column_major_upper_n1.json' );
var fixtureL1 = require( './fixtures/column_major_lower_n1.json' );
var fixtureU5 = require( './fixtures/column_major_upper_n5.json' );
var fixtureL5 = require( './fixtures/column_major_lower_n5.json' );
var roundingU = require( './fixtures/column_major_upper_rounding.json' );
var roundingL = require( './fixtures/column_major_lower_rounding.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlaqsp, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( dlaqsp.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var AP;
	var S;
	var i;

	values = [
		'foo',
		'bar',
		'row-major-invalid',
		123,
		true,
		null,
		void 0,
		{}
	];

	AP = new Float64Array( 6 );
	S = new Float64Array( 3 );

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaqsp( value, 'upper', 3, AP, S, 0.0125, 6.0 );
		};
	}
});

